package com.xyz.question_bank_management_system.modules.learning.service.impl;
import com.xyz.question_bank_management_system.modules.agent.mapper.PersonalizedResourceMapper;import com.xyz.question_bank_management_system.modules.learning.entity.ProfileEvidenceEvent;import com.xyz.question_bank_management_system.modules.learning.service.ProfileEvidenceConsumer;import com.xyz.question_bank_management_system.modules.profile.entity.StudentProfileSnapshot;import com.xyz.question_bank_management_system.modules.profile.model.ValidatedInteraction;import com.xyz.question_bank_management_system.modules.profile.service.ProfileAggregationService;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import java.time.LocalDateTime;
@Service @RequiredArgsConstructor public class ProfileEvidenceConsumerImpl implements ProfileEvidenceConsumer {private final PersonalizedResourceMapper mapper;private final ProfileAggregationService profile;public StudentProfileSnapshot apply(String eventId,ValidatedInteraction interaction){ProfileEvidenceEvent e=new ProfileEvidenceEvent();e.setEventId(eventId);e.setInteractionId(interaction.getId());e.setConsumerName("PROFILE_V1");e.setStatus("PROCESSING");mapper.insertEvidenceEvent(e);StudentProfileSnapshot s=profile.apply(interaction);mapper.markEvidenceProcessed(eventId,"PROFILE_V1");return s;}}
